<?php

declare(strict_types=1);

namespace App\Hosts\Protocol;

use App\Attributes\Generation\AutoGenerated;
use Spatie\LaravelData\Data;

/**
 * Why a host did not carry out an instruction.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
#[AutoGenerated('protocol/host.json')]
enum HostRefusal: string
{
    case GuardMoved = 'guard_moved';
    case NotRunning = 'not_running';
    case Expired = 'expired';
    case Unsafe = 'unsafe';
    case HostRestarted = 'host_restarted';
    case Fenced = 'fenced';
    case UnknownInstruction = 'unknown_instruction';
    case ImageFault = 'image_fault';

    /**
     * The fields a refused answer names, so the journal can say why the host refused.
     */
    public const array ANSWER_FIELDS = ['refusal', 'reason'];

    /**
     * Whether the facts of this refusal have a type of the protocol, so the journal reads them strictly.
     */
    public function hasTypedFacts(): bool
    {
        return match ($this) {
            self::ImageFault => true,
            default => false,
        };
    }

    /**
     * The Data the facts of this refusal are read into; the empty payload for a refusal whose facts have no type.
     *
     * @return class-string<Data>
     */
    public function factsPayload(): string
    {
        return match ($this) {
            self::ImageFault => Payloads\HostImageFaultFactsPayload::class,
            default => Payloads\HostEmptyPayload::class,
        };
    }
}
